// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *InsuranceJournalTemplate) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceJournalTemplateTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "test_report_id":
			column = "test_report_id"
		case "page_id":
			column = "page_id"
		case "posting_report_id":
			column = "posting_report_id"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Insurance_Journal_Template", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Insurance_Journal_Template.%s: %w", column, err)
		}
		switch column {
		case "test_report_id":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Insurance_Journal_Template.%s: %w", column, err)
			}
			t.Test_report_id = int(f)
		case "page_id":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Insurance_Journal_Template.%s: %w", column, err)
			}
			t.Page_id = int(f)
		case "posting_report_id":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Insurance_Journal_Template.%s: %w", column, err)
			}
			t.Posting_report_id = int(f)
		}
	}
	return nil
}

